def run(context):
    evidence = context.get('evidence_list', [])
    insights = {'insider_score': None, 'bulk_deal_summary': []}
    # Process evidence data
    for row in evidence:
        if row['type'] == 'insider_alert':
            insights['insider_score'] = max(insights['insider_score'], row['score'])
        elif row['type'] == 'bulk_block_deal':
            insights['bulk_deal_summary'].append(row)
    return insights

