WITH recent_breadth AS (SELECT sector, AVG(pct_above_50dma::numeric) AS avg_pct_above_50dma, AVG(change_5d::numeric) AS avg_change_5d FROM breadth.sector_daily WHERE snapshot_date >= CURRENT_DATE - INTERVAL '3 months' GROUP BY sector),
recent_stage AS (SELECT sector, AVG(stage2_pct) AS avg_stage2_pct FROM breadth.ma_pct_above WHERE snapshot_date >= CURRENT_DATE - INTERVAL '3 months' GROUP BY sector)
SELECT rb.sector, rb.avg_pct_above_50dma, rb.avg_change_5d, rs.avg_stage2_pct FROM recent_breadth rb JOIN recent_stage rs ON rb.sector = rs.sector ORDER BY rs.avg_stage2_pct DESC, rb.avg_pct_above_50dma DESC LIMIT 10;

